/**
 * Marketing 2.0 data, generated by backend/scripts/build_marketing2_assets.py from local runs.
 * Every exported object carries its provenance category (see PROVENANCE).
 */

export type Provenance = "real" | "reconstructed" | "illustrative";

export interface Candle {
  d: string;
  o: number;
  h: number;
  l: number;
  c: number;
}

export interface HeroData {
  symbol: string;
  weekly: Candle[];
  predictions: { d: string; p: number }[];
  threshold: number;
  samples: { date: string; start: string; p: number; label: number; file: string }[];
}

export interface TraceLayer {
  name: string;
  h: number;
  w: number;
  channels: number;
  active: number;
  files: string[];
}

export interface TraceData {
  sample: { date: string; start: string; label: number };
  p_label1: number;
  layers: TraceLayer[];
  gradcam_layer: string;
  input: string;
  gradcam: string;
}

export interface GridData {
  symbol: string;
  count: number;
  tp: number;
  sl: number;
  horizon: number;
  size: number;
  tiles: { file: string; start: string; end: string; label: number }[];
}

export interface TrainingData {
  run: string;
  dataset_id: string;
  generator_run_id: string;
  symbol: string;
  train_samples: number;
  val_samples: number;
  epochs_configured: number;
  epochs_trained: number;
  best_epoch: number;
  monitor: string;
  params: number;
  epochs: { e: number; loss: number; val_loss: number; acc: number; val_acc: number }[];
  arch: { name: string; kind: string; out: number[]; filters: number | null; params: number }[];
}

export interface BacktestData {
  run: string;
  model: string;
  test_n: number;
  benchmark_returns: Record<string, number>;
  symbol: string;
  period: [string, string];
  threshold: number;
  validation_n: number;
  costs: { commission: number; slippage: number };
  series: { d: string; s: number; spy: number; und: number; mix: number }[];
  threshold_curve: { t: number; precision: number; recall: number; f1: number }[];
  metrics: { total_return: number; max_drawdown: number; executed_trades: number; win_rate: number; sharpe: number };
  findings: { severity: string; title: string; interpretation: string }[];
}

export interface LabData {
  findings: { status: string; module: string; title: string; observation: string }[];
}

export interface FleetData {
  illustrative: true;
  t: string[];
  net_pnl: (number | null)[];
  bots: { name: string; symbol: string; status: string; ret: number; spark: (number | null)[] }[];
  counts: Record<string, number>;
  runs_24h: { ok: number; error: number; buy: number };
}

export interface OutcomeExample {
  decision: string;
  start: string;
  image: string;
  entry: { d: string; price: number };
  tp_price: number;
  sl_price: number;
  exit: { d: string; price: number; reason: "tp" | "sl" | "timeout"; bars_held: number };
  label: number;
  bars: Candle[];
}

/** Generated by backend/scripts/build_marketing2_outcome.py: real bars, labels verified against the dataset. */
export interface OutcomeData {
  provenance: string;
  symbol: string;
  rule: { tp: number; sl: number; horizon: number };
  convention: string;
  context_bars: number;
  examples: OutcomeExample[];
}

export type LabMethod = "gradcam" | "saliency" | "smoothgrad" | "occlusion";

export interface LabMapSample {
  date: string;
  start: string;
  label: number;
  p: number;
  input: string;
  gradcam: string;
  saliency: string;
  smoothgrad: string;
  occlusion: string;
  gradcam_all_zero: boolean;
  gradcam_on_candles: number;
  saliency_on_candles: number;
  occlusion_range: [number, number];
  foreground: number;
}

export interface LabMaps {
  provenance: string;
  model: string;
  layer: string;
  trace_index: number;
  samples: LabMapSample[];
  features: { name: string; h: number; channels: number; files: string[] }[];
  notes: Record<string, string>;
  colormaps: Record<"sequential" | "diverging" | "features", { name: string; stops: string[] }>;
}

export interface DomainData {
  provenance: string;
  layer: string;
  size: number;
  channels: number[];
  mri: { input: string; maps: string[]; source: string; copyright: string; gradcam: string; gradcam_source: string };
  chart: { input: string; maps: string[]; source: string; gradcam: string; gradcam_source: string };
}

const json = import.meta.glob("./data/*.json", { eager: true, import: "default" }) as Record<string, unknown>;
const images = import.meta.glob("./assets/*.png", { eager: true, query: "?url", import: "default" }) as Record<
  string,
  string
>;

function load<T>(name: string): T {
  const v = json[`./data/${name}.json`];
  if (!v) throw new Error(`marketing2: missing data/${name}.json — run build_marketing2_assets.py`);
  return v as T;
}

export const asset = (file: string): string => images[`./assets/${file}`] ?? "";

/** Screenshots of real result pages (see Showcase). */
const screens = import.meta.glob("./assets/screen_*.webp", { eager: true, query: "?url", import: "default" }) as Record<string, string>;
export const screen = (name: string): string => screens[`./assets/screen_${name}.webp`] ?? "";

export const hero = load<HeroData>("hero");
export const trace = load<TraceData>("trace");
export const grid = load<GridData>("grid");
export const training = load<TrainingData>("training");
export const backtest = load<BacktestData>("backtest");
export const lab = load<LabData>("lab");
export const fleet = load<FleetData>("fleet");
/** Generated by backend/scripts/build_marketing2_lab_assets.py. */
export const labmaps = load<LabMaps>("labmaps");
export const outcome = load<OutcomeData>("outcome");
/** Generated by backend/scripts/build_marketing2_domain_assets.py. */
export const domain = load<DomainData>("domain");

/** The real MSFT research chain behind the hero, trainer, analysis and backtest visuals. */
